new='''class PythonArrowExtractor(BaseArrowExtractor[dict, list, dict]):
    def extract_row(self, pa_table: pa.Table) -> dict:
        return _unnest(pa_table.to_pydict())

    def extract_column(self, pa_table: pa.Table) -> list:
        column = pa_table.column(0)
        # Fast path for primitive numeric columns without nulls.
        # Arrow's generic to_pylist() boxes values one by one in Python and is
        # comparatively slow for large numeric columns. NumPy can view/copy the
        # Arrow buffers in C and list conversion from a NumPy array is much
        # faster while returning the same Python scalar values for these types.
        if (
            pa.types.is_integer(column.type)
            or pa.types.is_floating(column.type)
            or pa.types.is_boolean(column.type)
        ) and column.null_count == 0:
            try:
                if isinstance(column, pa.ChunkedArray):
                    if len(column.chunks) == 1:
                        return column.chunk(0).to_numpy(zero_copy_only=False).tolist()
                    return np.asarray(column).tolist()
                return column.to_numpy(zero_copy_only=False).tolist()
            except (pa.ArrowInvalid, pa.ArrowNotImplementedError, TypeError, ValueError):
                pass
        return column.to_pylist()

    def extract_batch(self, pa_table: pa.Table) -> dict:
        return pa_table.to_pydict()
'''
if old not in s:
    raise SystemExit('old extractor block not found')
p.write_text(s.replace(old,new))
